mt19937 gen(time(0));

vector<int> e(MAXC + 5);

void precalc() {
    vector<int> p;
    for (int i = 2; i <= MAXC; i++) {
        if (e[i] == 0) {
            e[i] = i;
            p.pb(i);
        }
        for (int j = 0; j < (int)p.size() && p[j] * i <= MAXC && p[j] <= e[i]; j++) {
            e[p[j] * i] = p[j];
        }
    }
}

int f(int x) {
    int ans = 1;
    vector<int> p;
    while (x > 1) {
        p.pb(e[x]);
        x /= e[x];
    }
    for (int i = 0; i < (int)p.size(); i++) {
        if (i + 1 == (int)p.size() || p[i + 1] != p[i]) ans *= p[i];
    }
    return ans;
}

void gauss(int need, vector<int> &lst, vector<int> &ans, vector<vector<int>> &sz, vector<vector<vector<int>>> &v) {
    int n = lst.size();
    vector<bitset<20>> a(n);
    for (int i = 0; i < n; i++) a[i] = lst[i];
    bitset<20> b = need;
    vector<bitset<260>> l(n);
    for (int i = 0; i < n; i++) l[i][i] = 1;
    int i = 0;
    vector<int> col(20, -1);
    int bas_sz = 0;
    for (int j = 0; j < 20 && i < n; j++) {
        int i1 = i;
        while (i1 < n && a[i1][j] == 0) i1++;
        if (i1 == n) continue;
        swap(a[i], a[i1]);
        swap(l[i], l[i1]);
        bas_sz++;
        col[j] = i;
        for (int i2 = i + 1; i2 < n; i2++) {
            if (a[i2][j]) {
                a[i2] ^= a[i];
                l[i2] ^= l[i];
            }
        }
        i++;
    }
    bitset<20> res;
    bitset<260> path;
    for (int j = 0; j < 20; j++) {
        if (res[j] != b[j] && col[j] == -1) {
            exit(0);
        }
        if (res[j] == b[j]) continue;
        res ^= a[col[j]];
        path ^= l[col[j]];
    }
    if (a.back().count() != 0) {
        for (int i = 0; i < n; i++) {
            if (path[i]) ans.pb(lst[i]);
        }
        return;
    } 
    vector<int> diff_sz(300);
    sz.pb();
    v.pb();
    for (int it = 0; it < 100; it++) {
        bitset<260> now = path;
        for (int i = 0; i < n - bas_sz; i++) {
            if (gen() % 2) now ^= l[bas_sz + i];
        }
        int now_sz = now.count();
        if (diff_sz[now_sz]) continue;
        v.back().pb();
        for (int i = 0; i < n; i++) {
            if (now[i]) v.back().back().pb(lst[i]);
        }
        diff_sz[now_sz] = 1;
        sz.back().pb(now_sz);
    }
}

